import { lerp, clamp, ease } from "./helpers";

export const RX = 32;
export const RY = 24;

export default function HeroCard({ card, progress, vw, cardCenterOffsetVh = 0 }) {
  /*
   * ── Orbit radii ──
   * Desktop (lg ≥ 1024): UNCHANGED — 40vw / 30vh
   * Tablet  (md 600–1023): slightly tighter
   * Mobile  (sm 400–599):  compact orbit
   * XSmall  (xs < 400):    tight
   */
  const rx = vw >= 1024 ? 40
           : vw >= 600  ? 32
           : vw >= 400  ? 36
           :              34;

  const ry = vw >= 1024 ? 30
           : vw >= 600  ? 22
           : vw >= 400  ? 24
           :              22;

  /* ── Card dimensions ── */
  const cardWidth  = vw >= 1024 ? 190
                   : vw >= 600  ? 142
                   : vw >= 400  ? 100
                   :              86;

  const cardHeight = vw >= 1024 ? 234
                   : vw >= 600  ? 175
                   : vw >= 400  ? 123
                   :              106;

  const borderRad  = vw >= 1024 ? 20
                   : vw >= 600  ? 13
                   :              9;

  /*
   * ── Explode distance ──
   * Desktop unchanged (172).
   */
  const explodeDist = vw >= 1024 ? 172
                    : vw >= 600  ? 126
                    : vw >= 400  ? 96
                    :              80;

  const rad = (card.angle * Math.PI) / 180;
  const ox  = Math.cos(rad) * rx;
  const oy  = -Math.sin(rad) * ry;
  const mag = Math.sqrt(ox * ox + oy * oy) || 1;
  const EX  = (ox / mag) * explodeDist;
  const EY  = (oy / mag) * explodeDist;

  const t       = ease(clamp((progress - 0.35) / 0.55, 0, 1));
  const tx      = lerp(ox, EX, t);
  const ty      = lerp(oy, EY, t);
  const opacity = lerp(1, 0, clamp((progress - 0.65) / 0.3, 0, 1));

  const shadowMag = vw >= 600 ? 6 : 4;
  const shadowX   = +(Math.cos(rad) * shadowMag).toFixed(1);
  const shadowY   = -(Math.sin(rad) * shadowMag).toFixed(1);

  const tiltScale  = vw >= 1024 ? 1 : vw >= 600 ? 0.7 : 0.4;
  const rotateXDeg = (Math.sin(rad) * 6 * tiltScale).toFixed(1);
  const rotateYDeg = (-(Math.cos(rad) * 4 * tiltScale)).toFixed(1);

  /*
   * cardCenterOffsetVh shifts the orbit anchor point downward on mobile
   * so the card ring occupies the middle zone of the screen, leaving the
   * top and bottom clear for title and subtitle text.
   *
   * On desktop cardCenterOffsetVh = 0, so this has zero effect.
   * `ty` is in vw units (used as vw on left, as vh on top) — we keep the
   * existing `ty` in the top calc but add the offset as a separate vh value.
   */
  const topCalc  = `calc(50% + ${ty}vh + ${cardCenterOffsetVh}vh)`;
  const leftCalc = `calc(50% + ${tx}vw)`;

  return (
    <div
      style={{
        position: "absolute",
        left: leftCalc,
        top: topCalc,
        transform: `
          translate(-50%, -50%)
          perspective(800px)
          rotate(${card.rotate}deg)
          rotateX(${rotateXDeg}deg)
          rotateY(${rotateYDeg}deg)
        `,
        opacity,
        zIndex: card.z,
        willChange: "transform, opacity",
        pointerEvents: "none",
        filter: `drop-shadow(${shadowX}px ${shadowY}px 18px rgba(0,0,0,0.60))
                 drop-shadow(0px 4px 8px rgba(0,0,0,0.30))`,
      }}
    >
      <div
        style={{
          width: cardWidth,
          height: cardHeight,
          borderRadius: borderRad,
          overflow: "hidden",
          display: "flex",
          flexDirection: "column",
          position: "relative",
          boxShadow: "inset 0 0 0 1px rgba(255,255,255,0.10)",
        }}
      >
        <div style={{ flex: 1, position: "relative", overflow: "hidden" }}>
          <img
            src={`/assets/img${card.id}.png`}
            alt=""
            style={{
              width: "100%",
              height: "100%",
              objectFit: "cover",
              display: "block",
            }}
          />
        </div>
      </div>
    </div>
  );
}
